import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

void main() {
  runApp(const FoodApp());
}

class Food {
  final String name;
  final String image;
  final double price;
  final double rating;

  const Food(this.name, this.image, this.price, this.rating);
}

const List<Food> foods = [
  Food('Cheese Burger', 'burger', 8.5, 4.5),
  Food('Margherita Pizza', 'pizza', 12.0, 4.7),
  Food('Chicken Biryani', 'biryani', 10.0, 4.8),
  Food('Pasta Alfredo', 'pasta', 9.5, 4.2),
  Food('Crispy Samosa', 'samosa', 3.0, 4.0),
  Food('Butter Chicken', 'butterchicken', 11.0, 4.6),
  Food('Sweet Dessert', 'dessert', 5.5, 4.9),
  Food('Masala Dosa', 'dosa', 7.0, 4.1),
];

class FoodApp extends StatefulWidget {
  const FoodApp({super.key});

  @override
  State<FoodApp> createState() => _FoodAppState();
}

class _FoodAppState extends State<FoodApp> {
  ThemeMode _mode = ThemeMode.light;

  ThemeData _buildTheme(Brightness brightness) {
    final ColorScheme scheme = ColorScheme.fromSeed(
      seedColor: Colors.deepOrange,
      brightness: brightness,
    );
    return ThemeData(
      useMaterial3: true,
      colorScheme: scheme,
      fontFamily: 'Poppins',
      textTheme: const TextTheme(
        titleMedium: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
        bodyMedium: TextStyle(fontSize: 14),
        labelLarge: TextStyle(fontSize: 13, fontWeight: FontWeight.w600),
      ),
      appBarTheme: AppBarTheme(
        backgroundColor: scheme.primary,
        foregroundColor: scheme.onPrimary,
      ),
    );
  }

  void _toggleTheme() {
    setState(() {
      _mode = _mode == ThemeMode.light ? ThemeMode.dark : ThemeMode.light;
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'Food Menu',
      theme: _buildTheme(Brightness.light),
      darkTheme: _buildTheme(Brightness.dark),
      themeMode: _mode,
      home: FoodMenuScreen(
        isDark: _mode == ThemeMode.dark,
        onToggle: _toggleTheme,
      ),
    );
  }
}

class FoodMenuScreen extends StatelessWidget {
  final bool isDark;
  final VoidCallback onToggle;

  const FoodMenuScreen({
    super.key,
    required this.isDark,
    required this.onToggle,
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Food Menu'),
        actions: [
          IconButton(
            tooltip: 'Switch theme',
            icon: Icon(isDark ? Icons.light_mode : Icons.dark_mode),
            onPressed: onToggle,
          ),
        ],
      ),
      body: LayoutBuilder(
        builder: (context, constraints) {
          if (constraints.maxWidth >= 600) {
            return GridView.builder(
              padding: const EdgeInsets.all(12),
              gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                maxCrossAxisExtent: 260,
                childAspectRatio: 0.85,
                crossAxisSpacing: 12,
                mainAxisSpacing: 12,
              ),
              itemCount: foods.length,
              itemBuilder: (context, index) {
                return FoodCard(food: foods[index], vertical: true);
              },
            );
          }
          return ListView.builder(
            padding: const EdgeInsets.all(12),
            itemCount: foods.length,
            itemBuilder: (context, index) {
              return SizedBox(
                height: 110,
                child: FoodCard(food: foods[index], vertical: false),
              );
            },
          );
        },
      ),
    );
  }
}

class FoodCard extends StatelessWidget {
  final Food food;
  final bool vertical;

  const FoodCard({super.key, required this.food, required this.vertical});

  Widget _buildImage(BuildContext context) {
    return Stack(
      fit: StackFit.expand,
      children: [
        Image.memory(
          imageBytes(food.image),
          fit: BoxFit.cover,
          gaplessPlayback: true,
          errorBuilder: (context, error, stackTrace) {
            return Container(
              color: Theme.of(context).colorScheme.primaryContainer,
              alignment: Alignment.center,
              child: const Icon(Icons.fastfood, size: 40),
            );
          },
        ),
        Positioned(
          top: 6,
          right: 6,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
            decoration: BoxDecoration(
              color: Colors.black54,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                const Icon(Icons.star, size: 14, color: Colors.amber),
                const SizedBox(width: 2),
                Text(
                  food.rating.toString(),
                  style: const TextStyle(color: Colors.white, fontSize: 12),
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildInfo(BuildContext context) {
    final ThemeData theme = Theme.of(context);
    return Padding(
      padding: const EdgeInsets.all(10),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        mainAxisAlignment: MainAxisAlignment.center,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            food.name,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: theme.textTheme.titleMedium,
          ),
          const SizedBox(height: 4),
          Text(
            '\$${food.price.toStringAsFixed(2)}',
            style: theme.textTheme.labelLarge?.copyWith(
              color: theme.colorScheme.primary,
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Card(
      clipBehavior: Clip.antiAlias,
      elevation: 3,
      margin: vertical ? EdgeInsets.zero : const EdgeInsets.only(bottom: 10),
      child: vertical
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Expanded(child: _buildImage(context)),
                _buildInfo(context),
              ],
            )
          : Row(
              children: [
                SizedBox(width: 120, child: _buildImage(context)),
                Expanded(child: _buildInfo(context)),
              ],
            ),
    );
  }
}

// Images are embedded as base64, so no assets folder is needed.
final Map<String, Uint8List> _cache = {};

Uint8List imageBytes(String key) {
  return _cache.putIfAbsent(key, () => base64Decode(imageData[key]!));
}

const Map<String, String> imageData = {
  'burger':
      '',
  'pizza':
      '',
  'biryani':
      '',
  'pasta':
      '',
  'samosa':
      '',
  'butterchicken':
      '',
  'dessert':
      '',
  'dosa':
      '',
};
